<?php
declare(strict_types=1);
namespace App\Application\Review\Service;
use App\Domain\Review\Entity\UserConceptMastery;use App\Domain\Review\Enum\MasteryConfidence;use App\Domain\Review\Repository\UserConceptMasteryRepositoryInterface;use App\Domain\Review\Repository\UserFlashcardProgressRepositoryInterface;use App\Domain\Review\ValueObject\FlashcardProgressState;
final readonly class ApplyNotebookAnalysisSignalsService { public function __construct(private UserConceptMasteryRepositoryInterface $mastery,private UserFlashcardProgressRepositoryInterface $progress){} public function updateMastery(string $userId,string $conceptId,float $confidence,\DateTimeImmutable $now):void{$current=$this->mastery->find($userId,$conceptId);$count=($current?->evidenceCount??0)+1;$signals=$current?->signals??[];$signals['analysis_confidence']=$confidence;$this->mastery->save(new UserConceptMastery($userId,$conceptId,$current?->masteryScore,$count<10?MasteryConfidence::INSUFFICIENT:MasteryConfidence::LOW,$count,$now,$signals,$now));} public function advance(string $userId,string $flashcardId,\DateTimeImmutable $now):void{$progress=$this->progress->find($userId,$flashcardId);if($progress===null)return;$state=$progress->state();$progress->apply(new FlashcardProgressState($now,0,$state->easeFactor,$state->repetitions,$state->lapses),$now);$this->progress->save($progress);} }
